<script module lang="ts">
/**
 * Small read-only label for status or category (`design/components/badge.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/badge.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Icon, SlotText, joinSlot, type IconRole } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/badge.module.css'

export type BadgeTone = NonNullable<BadgeProps['tone']>

export type BadgeVariant = NonNullable<BadgeProps['variant']>

export interface BadgeProps {
  /**
   * Short text, about two words at most. A dot does not draw it and keeps it for assistive
   * technology. Required unless `count` is given.
   */
  children?: Snippet
  /**
   * A number drawn in the text's place. Past `max` it reads as `max` and a plus sign. Zero or
   * less draws nothing.
   */
  count?: number
  /**
   * A mark with no number, for "something is new". `children` names it to a screen reader;
   * without `children` it is hidden from assistive technology.
   */
  dot?: boolean
  /**
   * Leading and decorative; the text carries the meaning. Not drawn by a count or a dot.
   */
  icon?: IconRole
  /**
   * The largest count drawn as it is; default 99.
   */
  max?: number
  tone?: 'info' | 'warning' | 'success' | 'accent' | 'danger' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}
</script>

<script lang="ts">
let {
  children,
  count,
  dot = false,
  icon,
  max = 99,
  tone = 'neutral',
  variant = 'soft',
}: BadgeProps = $props()
const joined = joinSlot(undefined, () => ({}))
const shown = $derived(count === undefined ? '' : count > max ? String(max) + '+' : String(count))
const childrenText = new SlotText(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if count !== undefined
    }{#if count > 0
      }<span
        class={styles.badge}
        data-variant={variant}
        data-tone={tone}
        data-count=""
        data-member="badge"
        >{shown
      }</span
    >{/if
  }{:else if dot
    }<span
      class={styles.badge}
      data-variant={variant}
      data-tone={tone}
      aria-hidden={childrenText.current === '' ? true : undefined}
      data-dot=""
      data-member="badge"
      >{#if childrenText.current !== ''
        }<span class={styles.spoken}>{@render children?.()}</span
      >{/if
    }</span
  >{:else
    }<span class={styles.badge} data-variant={variant} data-tone={tone} data-member="badge"
      >{#if icon !== undefined}<span class={styles.glyph}><Icon name={icon} size="sm" /></span>{/if
      }{@render children?.()
    }</span
  >{/if
}{/if
}{@render joined.end?.()}
